import{_ as o,C as l,o as i,c as n,j as a,a as t,E as s,ae as u}from"./chunks/framework.C4zpkcTP.js";const g=JSON.parse('{"title":"Principles","description":"Better Laravel is built on Routes, Domains, Modules, Controllers, Features, Requests, Operations, and Jobs — each with a single clear responsibility.","frontmatter":{"title":"Principles","description":"Better Laravel is built on Routes, Domains, Modules, Controllers, Features, Requests, Operations, and Jobs — each with a single clear responsibility."},"headers":[],"relativePath":"better-laravel/principles.md","filePath":"better-laravel/principles.md"}'),p={name:"better-laravel/principles.md"};function c(d,e,h,b,m,f){const r=l("SequenceDiagram");return i(),n("div",null,[e[0]||(e[0]=a("h1",{id:"principles",tabindex:"-1"},[t("Principles "),a("a",{class:"header-anchor",href:"#principles","aria-label":'Permalink to "Principles"'},"​")],-1)),e[1]||(e[1]=a("blockquote",null,[a("p",null,"Better Laravel is not a new framework — it is a set of principles you can follow to build a better Laravel application. Just follow them and your application will turn into cleaner, more human-readable code.")],-1)),e[2]||(e[2]=a("h2",{id:"request-lifecycle",tabindex:"-1"},[t("Request lifecycle "),a("a",{class:"header-anchor",href:"#request-lifecycle","aria-label":'Permalink to "Request lifecycle"'},"​")],-1)),s(r,{title:"Serving a request",participants:["Route","Controller","Feature","Operation","Job"],steps:[{from:"Route",to:"Controller",label:"POST /api/v1/blogs",detail:"routes/api/v1/blogs.php"},{from:"Controller",to:"Feature",label:"serve(new StoreBlogFeature)"},{from:"Feature",to:"Feature",label:"Validate the Request",detail:"StoreBlogRequest type-hinted on handle()"},{from:"Feature",to:"Job",label:"run(new StoreBlogJob($data))"},{from:"Job",to:"Feature",label:"Blog",response:!0},{from:"Feature",to:"Operation",label:"run(new NotifySubscribersOperation($blog))"},{from:"Operation",to:"Job",label:"runInQueue(new NotifyViaEmailJob($blog))",detail:"pushed onto the queue"},{from:"Feature",to:"Controller",label:"Blog",response:!0},{from:"Controller",to:"Route",label:"HTTP response",response:!0}]}),e[3]||(e[3]=u('<h2 id="units" tabindex="-1">Units <a class="header-anchor" href="#units" aria-label="Permalink to &quot;Units&quot;">​</a></h2><h3 id="routes" tabindex="-1">Routes <a class="header-anchor" href="#routes" aria-label="Permalink to &quot;Routes&quot;">​</a></h3><p>Routes are the same as Laravel&#39;s default routes. The only difference is that Better Laravel loads routes from the <code>BetterLaravelServiceProvider</code>. You have 100% control over them. See more at:</p><ul><li><a href="/better-laravel/configuration.html#config">Configuration</a></li><li><a href="https://github.com/laranex/better-laravel/blob/master/src/BetterLaravelServiceProvider.php" target="_blank" rel="noreferrer">BetterLaravelServiceProvider.php</a></li></ul><h3 id="domain" tabindex="-1">Domain <a class="header-anchor" href="#domain" aria-label="Permalink to &quot;Domain&quot;">​</a></h3><p>Domain is where your business logic lives. A domain can have:</p><ul><li>Jobs</li><li>Requests</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Resources under domains are <strong>sharable</strong> across the application and consumed by Features. Since these are served globally, you can consume any of them from any module — no limitation at all.</p></div><h3 id="module" tabindex="-1">Module <a class="header-anchor" href="#module" aria-label="Permalink to &quot;Module&quot;">​</a></h3><p>Modules are where you wrap your business layers into separate units. A module can have:</p><ul><li>HTTP <ul><li>Controllers</li></ul></li><li>Features</li><li>Operations</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Resources under modules are <strong>not sharable</strong> across the application and are intended for a single purpose. You can only consume these resources from within the same module.</p></div><h3 id="controller" tabindex="-1">Controller <a class="header-anchor" href="#controller" aria-label="Permalink to &quot;Controller&quot;">​</a></h3><p>Controller is responsible for:</p><ul><li>Serving the Feature</li><li>Returning everything the Feature returns to the request</li></ul><h3 id="feature" tabindex="-1">Feature <a class="header-anchor" href="#feature" aria-label="Permalink to &quot;Feature&quot;">​</a></h3><p>Feature is responsible for:</p><ul><li>Validating the Request</li><li>Running Job(s) / Operation(s)</li><li>Mapping data from Job(s) to a response</li><li>Returning the HTTP Response to the Controller</li></ul><h3 id="request" tabindex="-1">Request <a class="header-anchor" href="#request" aria-label="Permalink to &quot;Request&quot;">​</a></h3><p>Request is responsible for:</p><ul><li>Validating the incoming HTTP Request</li><li>Authorization of the Request</li></ul><h3 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h3><p>Operation is responsible for:</p><ul><li>Running the Job(s)</li></ul><h3 id="job" tabindex="-1">Job <a class="header-anchor" href="#job" aria-label="Permalink to &quot;Job&quot;">​</a></h3><p>Job is responsible for:</p><ul><li>Handling Laravel Models</li><li>Providing data to the Feature</li></ul><h3 id="operation-vs-feature" tabindex="-1">Operation vs Feature <a class="header-anchor" href="#operation-vs-feature" aria-label="Permalink to &quot;Operation vs Feature&quot;">​</a></h3><p>Even though both Operation and Feature run Job(s), there is a key difference:</p><ul><li>Feature can be served from the Controller; Operation cannot.</li><li>Operation can only be run from a Feature — it cannot work independently.</li><li>Operation is optional in an application; Feature is not.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Operation is useful when the same set of Jobs needs to run from multiple Features. Instead of duplicating Job calls across Features, collect those Jobs into a single Operation and run it from each Feature.</p></div>',31))])}const q=o(p,[["render",c]]);export{g as __pageData,q as default};
